function person(id,x,y,t=0,moving=false,size=93,flip=false){ellipse(x,y-3,size*.22,7,'#12172844');if(moving&&id>=1&&id<=5)pose(id-1,1+(Math.floor(t*7)%2),x,y+Math.sin(t*14)*1.5,size,flip);else sprite(id,x,y+(moving?Math.sin(t*13)*3:Math.sin(t*2)*.7),size)}

function bubble(t,x,y,color=palette.cream){const width=Math.max(35,t.length*7.4+18);panel(x-width/2,y-23,width,26,'#182239',color);rect(x-3,y+2,6,6,color);text(t,x,y-9,12,color)}
