function floorTiles(y=180,colorA='#b2a38e',colorB='#a79783',size=40){rect(0,y,W,H-y,colorA);for(let row=0;row<(H-y)/size;row++)for(let col=0;col<W/size;col++){if((row+col)%2)rect(col*size,y+row*size,size,size,colorB);rect(col*size,y+row*size,size,1,'#ffffff0a')}}
function wall(base='#566c6c',floor='#ad9c87'){rect(0,0,W,180,base);for(let x=0;x<W;x+=48){rect(x,0,2,180,'#17213418');rect(x+4,0,1,180,'#ffffff09')}rect(0,160,W,17,'#34434a');rect(0,178,W,7,'#182334');floorTiles(185,floor,'#9f907f')}
function plant(x,y){rect(x-14,y-22,28,23,'#b9745c');rect(x-17,y-26,34,7,'#e09b72');rect(x-3,y-65,6,40,'#527250');rect(x-23,y-61,24,15,'#718e58');rect(x+1,y-73,22,21,'#8daa65');rect(x-12,y-89,20,24,'#678a54')}
