window.Concurrente={launch,goHome,catalog,get game(){return game},get paused(){return paused},get keys(){return keys},start(){if(!$('overlay').hidden)$('overlayButton').click()},step(seconds){const wasPaused=paused;paused=false;for(let i=0;i<seconds*60&&!game.finished;i++)game.tick(1/60);paused=wasPaused||game.finished;updateHUD();renderGame()},render:renderGame};

$('fullscreenButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.cabinet').requestFullscreen()}catch{report('El navegador no permite pantalla completa en este modo. Podés ampliar la ventana.')}};
